const readline = require("readline");

const rl = readline.createInterface({
  input: process.stdin,
  output: process.stdout,
});

rl.on("line", (line) => {
  const directives = line.split(" ");
  turnDice(directives);
});

function turnDice(directives) {
  const dice = new Dice();

  directives.forEach((directive) => {
    switch (directive) {
      case "L":
        dice.turnL();
        break;
      case "R":
        dice.turnR();
        break;
      case "F":
        dice.turnF();
        break;
      case "B":
        dice.turnB();
        break;
      case "A":
        dice.turnA();
        break;
      case "C":
        dice.turnC();
        break;
    }
  });

  dice.print();
}

class Dice {
  constructor() {
    this.left = 1;
    this.right = 2;
    this.front = 3;
    this.back = 4;
    this.top = 5;
    this.bottom = 6;
  }

  turnL() {
    // 前后不变，上变左，左变下，下变右，右变上
    let tmp = this.right;
    this.right = this.bottom;
    this.bottom = this.left;
    this.left = this.top;
    this.top = tmp;
  }

  turnR() {
    // 前后不变，上变右，右变下，下变左，左变上
    let tmp = this.left;
    this.left = this.bottom;
    this.bottom = this.right;
    this.right = this.top;
    this.top = tmp;
  }

  turnF() {
    // 左右不变，上变前，前变下，下变后，后变上
    let tmp = this.front;
    this.front = this.top;
    this.top = this.back;
    this.back = this.bottom;
    this.bottom = tmp;
  }

  turnB() {
    // 左右不变，前变上，上变后，后变下，下边前
    let tmp = this.top;
    this.top = this.front;
    this.front = this.bottom;
    this.bottom = this.back;
    this.back = tmp;
  }

  turnA() {
    // 上下不变， 前变右，右变后，后变左，左变前
    let tmp = this.right;
    this.right = this.front;
    this.front = this.left;
    this.left = this.back;
    this.back = tmp;
  }

  turnC() {
    // 上下不变， 右变前，前变左，左变后，后变右
    let tmp = this.front;
    this.front = this.right;
    this.right = this.back;
    this.back = this.left;
    this.left = tmp;
  }

  print() {
    let { left, right, front, back, top, bottom } = this;
    console.log(`${left}${right}${front}${back}${top}${bottom}`);
  }
}

